import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import {
    aiObservabilityInstrumentationChecklistDismissCreate,
    aiObservabilityInstrumentationChecklistRestoreCreate,
    aiObservabilityInstrumentationChecklistRetrieve,
} from '../../generated/api'
import { AIObservabilityInstrumentationCheckEnumApi, InstrumentationChecklistApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface instrumentationLogicValues {
    checklist: InstrumentationChecklistApi | null
    checklistLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface instrumentationLogicActions {
    dismiss: (check: AIObservabilityInstrumentationCheckEnumApi) => AIObservabilityInstrumentationCheckEnumApi
    dismissFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    dismissSuccess: (
        checklist: InstrumentationChecklistApi,
        payload?: AIObservabilityInstrumentationCheckEnumApi
    ) => {
        checklist: InstrumentationChecklistApi
        payload?: AIObservabilityInstrumentationCheckEnumApi
    }
    loadChecklist: () => any
    loadChecklistFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadChecklistSuccess: (
        checklist: InstrumentationChecklistApi,
        payload?: any
    ) => {
        checklist: InstrumentationChecklistApi
        payload?: any
    }
    restore: (check: AIObservabilityInstrumentationCheckEnumApi) => AIObservabilityInstrumentationCheckEnumApi
    restoreFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    restoreSuccess: (
        checklist: InstrumentationChecklistApi,
        payload?: AIObservabilityInstrumentationCheckEnumApi
    ) => {
        checklist: InstrumentationChecklistApi
        payload?: AIObservabilityInstrumentationCheckEnumApi
    }
}

export type instrumentationLogicType = MakeLogicType<instrumentationLogicValues, instrumentationLogicActions>

export const instrumentationLogic = kea<instrumentationLogicType>([
    path(['products', 'ai_observability', 'frontend', 'redesign', 'home', 'instrumentationLogic']),
    // Both write endpoints answer with the whole recomputed checklist, so a write installs its own response.
    loaders(() => {
        const projectId = (): string => String(ApiConfig.getCurrentProjectId())
        return {
            checklist: [
                null as InstrumentationChecklistApi | null,
                {
                    loadChecklist: async (): Promise<InstrumentationChecklistApi> =>
                        aiObservabilityInstrumentationChecklistRetrieve(projectId()),
                    dismiss: async (check: AIObservabilityInstrumentationCheckEnumApi) =>
                        aiObservabilityInstrumentationChecklistDismissCreate(projectId(), { check }),
                    restore: async (check: AIObservabilityInstrumentationCheckEnumApi) =>
                        aiObservabilityInstrumentationChecklistRestoreCreate(projectId(), { check }),
                },
            ],
        }
    }),
    afterMount(({ actions }) => {
        actions.loadChecklist()
    }),
])
